"""Distinct local-first App Factory experiences."""

def builders(shell):
    def capsule(app):
        body = '<section class="card"><label for="message">Note to your future self</label><textarea id="message" rows="5" maxlength="2000"></textarea><label for="date">Open on or after</label><input id="date" type="date"><button id="seal">Seal note</button><p id="feedback" role="status"></p></section><section class="card"><h2>Sealed notes</h2><div id="notes"></div></section>'
        script = """const K='begg:future-letter',message=document.getElementById('message'),date=document.getElementById('date'),notes=document.getElementById('notes'),feedback=document.getElementById('feedback');let entries;try{let value=JSON.parse(localStorage.getItem(K)||'[]');entries=Array.isArray(value)?value.filter(x=>x&&typeof x.text==='string'&&typeof x.date==='string'):[]}catch{entries=[]}const today=()=>new Date().toLocaleDateString('en-CA');date.min=today();function draw(){notes.replaceChildren();if(!entries.length){notes.textContent='No notes sealed yet.';return}entries.forEach((item,i)=>{let row=document.createElement('div');row.className='item';let text=document.createElement('span');text.textContent=item.date<=today()?item.text:'Sealed until '+item.date;let remove=document.createElement('button');remove.className='secondary';remove.textContent='Delete';remove.setAttribute('aria-label','Delete note for '+item.date);remove.addEventListener('click',()=>{entries.splice(i,1);save()});row.append(text,remove);notes.append(row)})}function save(){localStorage.setItem(K,JSON.stringify(entries));draw()}document.getElementById('seal').addEventListener('click',()=>{let text=message.value.trim();if(!text||!date.value||date.value<today()){feedback.textContent='Add a note and a future date.';return}entries.push({text,date:date.value});save();message.value='';feedback.textContent='Note sealed on this device.'});draw();"""
        return shell(app,body,script)

    def rhythm(app):
        body = '<section class="card"><label for="tempo">Tempo <output id="speed">100</output> BPM</label><input id="tempo" type="range" min="50" max="180" value="100"><div id="steps" style="display:grid;grid-template-columns:repeat(8,1fr);gap:6px;margin:20px 0"></div><div class="row"><button id="play">Play</button><button id="clear" class="secondary">Clear</button></div><p class="small">Tap steps to build an eight-beat rhythm. Sound starts when you press Play.</p></section>'
        script = """const K='begg:rhythm-lab',steps=document.getElementById('steps'),tempo=document.getElementById('tempo'),speed=document.getElementById('speed'),play=document.getElementById('play');let pattern;try{pattern=JSON.parse(localStorage.getItem(K)||'[]')}catch{pattern=[]}if(!Array.isArray(pattern)||pattern.length!==8||!pattern.every(x=>typeof x==='boolean'))pattern=[true,false,false,false,true,false,true,false];let pos=0,timer=null,audio=null;function draw(){steps.replaceChildren();pattern.forEach((on,i)=>{let b=document.createElement('button');b.textContent=String(i+1);b.setAttribute('aria-label','Beat '+(i+1));b.setAttribute('aria-pressed',String(on));b.style.background=on?'#79dcff':'#2a333d';b.style.color=on?'#051118':'#f3f6f8';b.style.outline=timer&&pos===i?'3px solid #ffc766':'none';b.addEventListener('click',()=>{pattern[i]=!pattern[i];localStorage.setItem(K,JSON.stringify(pattern));draw()});steps.append(b)})}function tick(){if(pattern[pos]&&audio){let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(pos%4===0?880:550,audio.currentTime);g.gain.setValueAtTime(.12,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.08)}draw();pos=(pos+1)%8}function stop(){clearInterval(timer);timer=null;play.textContent='Play';draw()}play.addEventListener('click',()=>{if(timer){stop();return}audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();pos=0;tick();timer=setInterval(tick,60000/Number(tempo.value)/2);play.textContent='Pause'});tempo.addEventListener('input',()=>{speed.textContent=tempo.value;if(timer){stop();play.click()}});document.getElementById('clear').addEventListener('click',()=>{pattern=Array(8).fill(false);localStorage.setItem(K,JSON.stringify(pattern));draw()});draw();"""
        return shell(app,body,script)

    def museum(app):
        body = '<section class="card"><label for="title">Object or moment</label><input id="title" maxlength="80" placeholder="A stone from the river"><label for="detail">Why keep it?</label><textarea id="detail" rows="3" maxlength="600"></textarea><button id="add">Add exhibit</button><p id="feedback" role="status"></p></section><section class="card"><div class="row"><h2>My exhibits</h2><button id="export" class="secondary">Export JSON</button></div><div id="exhibits"></div></section>'
        script = """const K='begg:tiny-museum',title=document.getElementById('title'),detail=document.getElementById('detail'),exhibits=document.getElementById('exhibits'),feedback=document.getElementById('feedback');let items;try{let value=JSON.parse(localStorage.getItem(K)||'[]');items=Array.isArray(value)?value.filter(x=>x&&typeof x.title==='string'&&x.title&&typeof x.detail==='string'&&typeof x.date==='string'):[]}catch{items=[]}function draw(){exhibits.replaceChildren();if(!items.length){exhibits.textContent='Your collection is empty.';return}items.forEach((item,i)=>{let card=document.createElement('article');card.className='item';let content=document.createElement('span');let name=document.createElement('strong');name.textContent=item.title;let note=document.createElement('p');note.textContent=item.detail;let stamp=document.createElement('small');stamp.textContent=item.date;content.append(name,note,stamp);let remove=document.createElement('button');remove.className='secondary';remove.textContent='Remove';remove.setAttribute('aria-label','Remove exhibit '+item.title);remove.addEventListener('click',()=>{items.splice(i,1);save()});card.append(content,remove);exhibits.append(card)})}function save(){localStorage.setItem(K,JSON.stringify(items));draw()}document.getElementById('add').addEventListener('click',()=>{if(!title.value.trim()){feedback.textContent='Name the exhibit first.';return}items.unshift({title:title.value.trim(),detail:detail.value.trim(),date:new Date().toLocaleDateString()});save();title.value='';detail.value='';feedback.textContent='Exhibit added.'});document.getElementById('export').addEventListener('click',()=>{let blob=new Blob([JSON.stringify(items,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tiny-museum.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});draw();"""
        return shell(app,body,script)

    def story(app):
        body = '<section class="card"><label for="seed">Your starting idea</label><input id="seed" maxlength="100" placeholder="An abandoned lighthouse"><button id="spin">Make a story prompt</button><div id="prompt" class="card" role="status" style="font-size:1.25rem;line-height:1.5">Add an idea and make a prompt.</div><button id="copy" class="secondary">Copy prompt</button></section>'
        script = """const places=['during a citywide blackout','at the edge of a floating market','on the last train of the night','inside a forgotten museum'],twists=['a stranger knows its secret','a message arrives from the future','the smallest detail changes everything','the map points back home'],limits=['Tell it in six sentences.','Begin with dialogue.','Use no character names.','End with a question.'];let output=document.getElementById('prompt');document.getElementById('spin').addEventListener('click',()=>{let seed=document.getElementById('seed').value.trim();if(!seed){output.textContent='Add a starting idea first.';return}let choose=a=>a[Math.floor(Math.random()*a.length)];output.textContent='Write about '+seed+' '+choose(places)+'. '+choose(twists)+'. '+choose(limits)});document.getElementById('copy').addEventListener('click',async()=>{if(output.textContent.startsWith('Write about ')){try{await navigator.clipboard.writeText(output.textContent)}catch{output.textContent+=' Select and copy this text.'}}});"""
        return shell(app,body,script)

    return {'time_capsule':capsule,'rhythm_lab':rhythm,'tiny_museum':museum,'story_splice':story}
